diff --git a/runtime/nvidia/op_gemm.cuh b/runtime/nvidia/op_gemm.cuh
index ae75cdc7..ee33fe39 100644
--- a/runtime/nvidia/op_gemm.cuh
+++ b/runtime/nvidia/op_gemm.cuh
@@ -2694,7 +2694,7 @@ static __device__ void d_gemv_fp8(__nv_bfloat16* __restrict__ C, const __nv_bflo
                            __nv_bfloat16* __restrict__ arena) {
 #if PLOW_NV_FP8_DECODE_WGMMA_ACTIVE
     if (gemv_fp8_wgmma_supported(M, K)) {
-        if (M == 8) d_gemv_fp8_wgmma<8, false>(C, x, W, nullptr, scale, nullptr, M, N, K, slice, nblk, arena);
+        if (M <= 8) d_gemv_fp8_wgmma<8, false>(C, x, W, nullptr, scale, nullptr, M, N, K, slice, nblk, arena);
         else d_gemv_fp8_wgmma<16, false>(C, x, W, nullptr, scale, nullptr, M, N, K, slice, nblk, arena);
         return;
     }
@@ -2948,7 +2948,7 @@ static __device__ void d_gemv_glu_fp8(__nv_bfloat16* __restrict__ C, const __nv_
                                unsigned nblk, __nv_bfloat16* __restrict__ arena) {
 #if PLOW_NV_FP8_DECODE_WGMMA_ACTIVE
     if (gemv_fp8_wgmma_supported(M, K) && act == PLOW_ACT_GELU_TANH_) {
-        if (M == 8) d_gemv_fp8_wgmma<8, true>(C, x, Wg, Wu, sg, su, M, N, K, slice, nblk, arena);
+        if (M <= 8) d_gemv_fp8_wgmma<8, true>(C, x, Wg, Wu, sg, su, M, N, K, slice, nblk, arena);
         else d_gemv_fp8_wgmma<16, true>(C, x, Wg, Wu, sg, su, M, N, K, slice, nblk, arena);
         return;
     }
diff --git a/runtime/nvidia/op_gemv_fp8_wgmma.cuh b/runtime/nvidia/op_gemv_fp8_wgmma.cuh
index 36e23a78..ab895c53 100644
--- a/runtime/nvidia/op_gemv_fp8_wgmma.cuh
+++ b/runtime/nvidia/op_gemv_fp8_wgmma.cuh
@@ -1,9 +1,13 @@
 #pragma once

 #define PLOW_NV_FP8_DECODE_WGMMA_ARENA_BYTES 70720u
+#ifndef PLOW_NV_FP8_DECODE_WGMMA_ALL_ROWS
+#define PLOW_NV_FP8_DECODE_WGMMA_ALL_ROWS 0
+#endif

 __device__ __forceinline__ bool gemv_fp8_wgmma_supported(unsigned M, unsigned K) {
-    return (M == 8 || M == 16) && K && !(K % 16) && blockDim.x == 256;
+    return (M == 8 || M == 16 || (PLOW_NV_FP8_DECODE_WGMMA_ALL_ROWS && M > 0 && M < 8))
+        && K && !(K % 16) && blockDim.x == 256;
 }

 template <unsigned Rows>
